export const findLocalExerciseGif = (exerciseName: string): string | null => {
  const normalized = exerciseName.toLowerCase().trim()
  
  // Try exact match first
  if (localExerciseGifs[normalized]) {
    return localExerciseGifs[normalized]
  }
  
  // Try partial matches
  for (const [key, path] of Object.entries(localExerciseGifs)) {
    if (normalized.includes(key) || key.includes(normalized)) {
      return path
    }
  }
  
  // Try keyword matching
  const words = normalized.split(/\s+/)
  for (const [key, path] of Object.entries(localExerciseGifs)) {
    const keyWords = key.split(/\s+/)
    if (words.some(word => keyWords.includes(word))) {
      return path
    }
  }
  
  return null
}

export const getLocalGifStats = () => ({
  totalGifs: Object.keys(localExerciseGifs).length,
  categories: {
    'chest': Object.values(localExerciseGifs).filter(path => path.includes('/chest/')).length,
    'back': Object.values(localExerciseGifs).filter(path => path.includes('/back/')).length,
    'shoulders': Object.values(localExerciseGifs).filter(path => path.includes('/shoulders/')).length,
    'arms': Object.values(localExerciseGifs).filter(path => path.includes('/arms/')).length,
    'legs': Object.values(localExerciseGifs).filter(path => path.includes('/legs/')).length,
    'core': Object.values(localExerciseGifs).filter(path => path.includes('/core/')).length,
    'cardio': Object.values(localExerciseGifs).filter(path => path.includes('/cardio/')).length,
    'full-body': Object.values(localExerciseGifs).filter(path => path.includes('/full-body/')).length
  }
})
